INSERT INTO menu_items(name, category_id, price, description, image_url, calories, proteins, fats,carbohydrates) VALUES
    ('Американо', 2, 165.0, 'Классический черный кофе с насыщенным ароматом, мягким вкусом и приятным продолжительным послевкусием. Идеальный выбор для тех, кто любит чистый вкус кофе без добавления молока.', '/img/menu/Americano.jpg', 1.0, 0.01, 0.04, 0.01),
    ('Эспрессо', 2, 109.0, 'Крепкий концентрированный кофе, приготовленный под высоким давлением. Обладает насыщенным вкусом, плотной текстурой и ярким кофейным ароматом — настоящая основа для истинных ценителей кофе.', '/img/menu/espresso.jpg', 0.93, 0.13, 0, 0.10),
    ('Латте', 2, 235.0, 'Нежный кофейный напиток с насыщенным эспрессо и большим количеством молока. Мягкий сливочный вкус и бархатистая текстура делают его идеальным выбором для тех, кто любит деликатный кофейный акцент.', '/img/menu/latte.jpg', 41.0, 2.02, 2.17, 3.17),
    ('Раф', 2, 230.0, 'Нежный кофейный напиток на основе эспрессо и сливок, взбитых до воздушной кремовой текстуры. Мягкий, насыщенный вкус с деликатной сладостью и бархатистым послевкусием.', '/img/menu/raf.jpg', 71.25, 1.82, 3.0, 4.45),
    ('Флэт уайт', 2, 205.0, 'Насыщенный кофейный напиток с двойной порцией эспрессо и тонким слоем шелковистой молочной микропены. Яркий вкус кофе, дополненный мягкой сливочной текстурой, для идеального баланса крепости и нежности.', '/img/menu/flat white.jpg', 40, 1.95, 2.10, 3.05),
    ('Апельсиновый эспрессо', 2, 185.0, 'Освежающий кофейный напиток, сочетающий крепкий эспрессо и яркий цитрусовый вкус апельсина. Бодрящий контраст сочной сладости и кофейной горчинки с приятным послевкусием.', '/img/menu/orange espresso.jpg', 29.50,	0.01, 0.23,	6.75),
    ('Капучино' ,  2, 240.0, 'Классический кофейный напиток с насыщенным эспрессо, нежным молоком и воздушной молочной пеной. Мягкий, сбалансированный вкус с бархатистой текстурой для настоящего удовольствия в каждой чашке.', '/img/menu/cappuccino.jpg', 40.67,	2.01, 2.17,	3.13);
